CREATE OR REPLACE FUNCTION public.coatria_image_preparation_broker_lock_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $guard$
BEGIN
 IF current_user=TG_ARGV[0] AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'Preparation authority rows are read only' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END
$guard$;
